  deep:   0x10365a, blue:  0x1d5c8f, blueLt: 0x417fa8,
  foam:   0xf7f3e6,
  hull:   0xc96a3a, hullDk: 0x8a3f22, deck: 0xe8d9b0,
  fuji:   0x2a4a6b, snow: 0xf5f1e4, mist: 0xcfc9b6,
};
const flat = (c,o={}) => new THREE.MeshLambertMaterial({color:c, flatShading:true, ...o});

const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(C.sky);
scene.fog = new THREE.Fog(C.sky, 70, 170);

const camera = new THREE.PerspectiveCamera(45, innerWidth/innerHeight, .1, 400);
camera.position.set(0, 8, 36);
camera.lookAt(2, 4, 0);

scene.add(new THREE.HemisphereLight(0xf2e8d0, C.deep, 1.0));
const sun = new THREE.DirectionalLight(0xfff4dc, .75);
sun.position.set(-20, 28, 20); scene.add(sun);

